## Code Example
```c
// digest_async.h
typedef void (*OnBlock)(size_t idx, const char* digest_hex, void* user);
typedef void (*OnComplete)(const char* out_json, void* user);

int digest_batch_async(
    const uint8_t** blocks,
    size_t n,
    size_t block_len,
    OnBlock on_block,
    OnComplete on_complete,
    void* user
);
```

```c
// digest_async.c
#include "digest_async.h"
#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>

static void SHA256_hex(const uint8_t* data, size_t len, char* out) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(data, len, hash);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++)
        sprintf(out + i * 2, "%02x", hash[i]);
}

static int build_result_json(
    const uint8_t** blocks, size_t n, size_t block_len,
    char** out_json
) {
    size_t buf_size = 64 * n + 32;
    char* buf = malloc(buf_size);
    if (!buf) return -1;

    char* p = buf;
    p += sprintf(p, "{\"results\":[");
    for (size_t i = 0; i < n; i++) {
        char hex[SHA256_DIGEST_LENGTH * 2 + 1];
        SHA256_hex(blocks[i], block_len, hex);
        p += sprintf(p, "{\"index\":%zu,\"digest\":\"%s\"},", i, hex);
    }
    p--; *p = ']';
    p += sprintf(p, "}");
    *out_json = buf;
    return 0;
}

int digest_batch_async(
    const uint8_t** blocks, size_t n, size_t block_len,
    OnBlock on_block, OnComplete on_complete, void* user
) {
    char hex[SHA256_DIGEST_LENGTH * 2 + 1];
    for (size_t i = 0; i < n; i++) {
        SHA256_hex(blocks[i], block_len, hex);
        on_block(i, hex, user);
    }

    char* json = NULL;
    int ret = build_result_json(blocks, n, block_len, &json);
    if (ret == 0) {
        on_complete(json, user);
        free(json);
    }
    return ret;
}
```

```go
// digest_cgo.go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -lcrypto
#include "digest_async.h"
#include <stdlib.h>

typedef struct {
    void* handle;
} GoCallbackContext;

extern void goOnBlock(size_t idx, const char* digest_hex, void* user);
extern void goOnComplete(const char* out_json, void* user);
*/
import "C"

import (
    "encoding/json"
    "fmt"
    "runtime"
    "sync"
)

type blockResult struct {
    Index  int    `json:"index"`
    Digest string `json:"digest"`
}

type batchResult struct {
    Results []blockResult `json:"results"`
}

var (
    mu       sync.Mutex
    callback = struct {
        perBlock []string
        batch    string
        done     chan struct{}
        err      error
    }{}
    registry = make(map[uint64]chan struct{})
)

export goOnBlock := func(idx C.size_t, digestHex *C.char, user unsafe.Pointer) {
    mu.Lock()
    defer mu.Unlock()
    if idx >= C.size_t(len(callback.perBlock)) {
        callback.perBlock = append(callback.perBlock, C.GoString(digestHex))
    }
}

export goOnComplete := func(jsonStr *C.char, user unsafe.Pointer) {
    defer C.free(unsafe.Pointer(jsonStr))
    mu.Lock()
    defer mu.Unlock()
    callback.batch = C.GoString(jsonStr)
    close(callback.done)
}

func DigestBatchAsync(blocks [][]byte) (perBlock []string, batch string, err error) {
    mu.Lock()
    callback.perBlock = make([]string, 0, len(blocks))
    callback.batch = ""
    callback.done = make(chan struct{})
    mu.Unlock()

    cBlocks := make([]*C.uint8_t, len(blocks))
    for i, b := range blocks {
        cBlocks[i] = (*C.uint8_t)(C.CBytes(b))
    }
    defer func() {
        for _, p := range cBlocks {
            C.free(unsafe.Pointer(p))
        }
    }()

    n := C.size_t(len(blocks))
    blockLen := C.size_t(0)
    if n > 0 {
        blockLen = C.size_t(len(blocks[0]))
    }

    ret := C.digest_batch_async(
        (**C.uint8_t)(&cBlocks[0]),
        n,
        blockLen,
        C.OnBlock(C.goOnBlock),
        C.OnComplete(C.goOnComplete),
        nil,
    )

    select {
    case <-callback.done:
    }

    mu.Lock()
    defer mu.Unlock()
    return callback.perBlock, callback.batch, nil
}

func main() {
    blocks := [][]byte{
        []byte("block1"),
        []byte("block2"),
        []byte("block3"),
    }

    perBlock, batch, err := DigestBatchAsync(blocks)
    if err != nil {
        fmt.Println("Error:", err)
        return
    }

    fmt.Println("Per-block digests:", perBlock)
    fmt.Println("Batch JSON:", batch)
}
```

## What to Look For
- Correct use of CGO `export` directives and callback registration
- Proper memory lifecycle: C allocations copied to Go then freed immediately
- Thread-safety via mutexes protecting shared callback state
- Worker pool implementation with proper goroutine cleanup and cancellation

## Why This Is Asked

This question tests understanding of Go-C interop boundaries, memory ownership, and callback-based asynchronous flows in CGO. The candidate must design a safe pattern for per-input callbacks, ordering guarantees, and memory cleanup under concurrency.

## Key Concepts

- CGO callbacks and //export directives
- Cross-language memory management (malloc/free)
- Synchronization and ordering in Go when callbacks arrive from C
- Safe memory copying between C and Go heaps

## Code Example

```go
package main

/*
#include <stdlib.h>
#include <string.h>

typedef struct {
    void *ctx;
    int index;
    const char *result;
    size_t len;
} CallbackContext;

extern void goCallback(CallbackContext *cbCtx);

static int batch_process_wrapper(
    const char **inputs,
    size_t n,
    void (*cb)(const char *result, size_t len, void *ctx),
    void *ctx
) {
    for (size_t i = 0; i < n; i++) {
        cb(inputs[i], strlen(inputs[i]), ctx);
    }
    return 0;
}

static void cCallback(const char *result, size_t len, void *ctx) {
    CallbackContext *cbCtx = (CallbackContext *)ctx;
    cbCtx->result = result;
    cbCtx->len = len;
    goCallback(cbCtx);
}

//export goCallback
extern void goCallback(CallbackContext *cbCtx);
*/
import "C"

import (
    "fmt"
    "sync"
    "unsafe"
)

type Result struct {
    Index int
    Data  string
    Err   error
}

func BatchProcess(inputs []string) ([]string, error) {
    if len(inputs) == 0 {
        return []string{}, nil
    }

    cInputs := make([]*C.char, len(inputs))
    defer func() {
        for _, cStr := range cInputs {
            C.free(unsafe.Pointer(cStr))
        }
    }()

    for i, s := range inputs {
        cStr := C.CString(s)
        cInputs[i] = cStr
    }

    results := make([]string, len(inputs))
    var wg sync.WaitGroup
    resultCh := make(chan Result, len(inputs))

    ctx := C.malloc(C.sizeof_char * C.size_t(len(inputs)))
    defer C.free(ctx)

    wrapper := func() {
        defer wg.Done()
        for i := 0; i < len(inputs); i++ {
            callbackCtx := &C.CallbackContext{
                ctx:   ctx,
                index: C.int(i),
            }
            ret := C.batch_process_wrapper((**C.char)(unsafe.Pointer(&cInputs[i])), 1, C.cCallback, unsafe.Pointer(callbackCtx))
            if ret != 0 {
                resultCh <- Result{Index: i, Err: fmt.Errorf("batch_process failed with code %d", ret)}
                return
            }
        }
    }

    wg.Add(1)
    go wrapper()

    go func() {
        wg.Wait()
        close(resultCh)
    }()

    for result := range resultCh {
        if result.Err != nil {
            return nil, result.Err
        }
        results[result.Index] = result.Data
    }

    return results, nil
}

func main() {
    inputs := []string{"hello", "world", "foo", "bar"}

    var wg sync.WaitGroup
    for i := 0; i < 4; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            results, err := BatchProcess(inputs)
            if err != nil {
                fmt.Printf("Goroutine %d: Error: %v\n", id, err)
                return
            }
            fmt.Printf("Goroutine %d: Results: %v\n", id, results)
        }(i)
    }

    wg.Wait()
    fmt.Println("All goroutines completed")
}
```

